package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of a sheet's settings and of the roles it gives user names, kept per sheet. */
@Repository
public class Settings {

    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String FLOOR_DEFAULT = "1.00";
    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";

    private final JdbcTemplate jdbc;

    public Settings(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The setting's value; "" when it was never set. */
    public String get(String sheetId, String key) {
        List<String> values = jdbc.queryForList("SELECT setting_value FROM setting WHERE sheet_id = ? AND setting_key = ?",
                String.class, sheetId, key);
        return values.isEmpty() ? "" : values.get(0);
    }

    public void set(String sheetId, String key, String value) {
        jdbc.update("MERGE INTO setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key) VALUES (?, ?, ?)",
                sheetId, key, value);
    }

    /** The clerk limit; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = get(sheetId, CLERK_LIMIT);
        return value.isEmpty() ? null : new BigDecimal(value);
    }

    /** The floor, with two decimals: what a claim's live due is at least; 1.00 when never set. */
    public BigDecimal floor(String sheetId) {
        String value = get(sheetId, FLOOR);
        return new BigDecimal(value.isEmpty() ? FLOOR_DEFAULT : value);
    }

    /** A live due raised to the sheet's floor; null (no due) stays null. */
    public BigDecimal floored(String sheetId, BigDecimal due) {
        return due == null ? null : due.max(floor(sheetId));
    }

    /** The sheet's roles, by user name. */
    public List<Role> roles(String sheetId) {
        return jdbc.query("SELECT * FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                (rs, n) -> new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role")), sheetId);
    }

    /** The user's role: clerk unless the sheet gave them another. */
    public String role(String sheetId, String user) {
        List<String> roles = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return roles.isEmpty() ? CLERK : roles.get(0);
    }

    public void save(Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                role.sheetId(), role.user(), role.role());
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettings {

    private static final Pattern AMOUNT = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?");

    // Both are kept with two decimals. A blank floor leaves the floor as it is; a blank clerk limit is no
    // limit, unless a floor is saved with it, when the clerk limit is left as it is (and null leaves it
    // as it is too). Anything else that is not an amount of 0.00 or more with up to two decimals is refused.
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest body,
            Out<SheetSettings> settingsOut) throws InvalidSettingException {
        String floor = body == null || body.floor() == null ? "" : body.floor().trim();
        if (!floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
            throw new InvalidSettingException("The floor must be an amount of 0.00 or more, with up to two decimals.");
        }
        String typed = body == null || body.clerkLimit() == null ? null : body.clerkLimit().trim();
        if (typed != null && !typed.isEmpty() && !AMOUNT.matcher(typed).matches()) {
            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more, with up to two decimals.");
        }
        if (typed == null && floor.isEmpty()) {
            typed = "";
        }
        String limit = typed == null || (typed.isEmpty() && !floor.isEmpty()) ? null
                : typed.isEmpty() ? "" : twoDecimals(typed);
        settingsOut.set(new SheetSettings(sheetId.trim(), limit, floor.isEmpty() ? null : twoDecimals(floor)));
    }

    private static String twoDecimals(String amount) {
        return new BigDecimal(amount).setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/** Works out a sheet's figures the way the screen shows them (claimed, due-total, and their totals). */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final People people;
    private final Claims claims;
    private final Rates rates;
    private final Sheets sheets;
    private final Settings settings;

    public Rollup(People people, Claims claims, Rates rates, Sheets sheets, Settings settings) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
    }

    public Figures figures(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> counting = claims.list(sheetId).stream()
                .filter(c -> c.status() == ClaimStatus.OPEN || c.status() == ClaimStatus.SETTLED).toList();
        Map<Long, Figures.PersonFigures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        BigDecimal dueTotal = ZERO;
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            boolean anyFigure = false;
            for (Claim claim : counting) {
                if (claim.personId() != person.id() || !counts(claim, person)) {
                    continue;
                }
                claimed = claimed.add(claim.amount());
                BigDecimal figure = figure(claim, person);
                if (figure != null) {
                    due = due.add(figure);
                    anyFigure = true;
                }
            }
            // With no rate today and no figure, the due-total is n/a.
            boolean none = !anyFigure && rates.on(sheetId, person.grade(), today) == null;
            claimedTotal = claimedTotal.add(claimed);
            if (!none) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.id(), new Figures.PersonFigures(person.name(), claimed.toPlainString(),
                    none ? "n/a" : due.toPlainString()));
        }
        return new Figures(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** The figures of the sheet's counting claims dated from {@code from} to {@code to} inclusive, those without one skipped. */
    public BigDecimal dueTotal(String sheetId, LocalDate from, LocalDate to) {
        BigDecimal total = ZERO;
        for (Claim claim : claims.list(sheetId)) {
            if ((claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.SETTLED)
                    || claim.date().isBefore(from) || claim.date().isAfter(to)) {
                continue;
            }
            Person person = people.find(sheetId, claim.personId());
            if (person != null && !counts(claim, person)) {
                continue;
            }
            BigDecimal figure = person == null ? claim.settledDue() : figure(claim, person);
            if (figure != null) {
                total = total.add(figure);
            }
        }
        return total;
    }

    /** Whether the (OPEN or SETTLED) claim counts: a held person's OPEN claims count in no live total. */
    private static boolean counts(Claim claim, Person person) {
        return !(person.held() && claim.status() == ClaimStatus.OPEN);
    }

    /**
     * The claim's figure (null when it has none): a settled claim's frozen due, otherwise the figure its person's
     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, half to even, raised to the floor.
     */
    private BigDecimal figure(Claim claim, Person person) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated()) {
            return claim.statedDue();
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.grade(), claim.date());
        return rate == null ? null : settings.floored(claim.sheetId(), claim.amount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN));
    }
}
package net.officefloor.hq.app.claim;

