  return rest > 5000n || (rest === 5000n && cents % 2n === 1n) ? cents + 1n : cents;
}

/** `amount` times `rate` percent with two decimals, or n/a when there is no rate. */
export function due(amount: string, rate: string | undefined): string {
  return rate === undefined ? 'n/a' : show(dueCents(amount, rate));
}

/** Due figures added up, skipping n/a. */
export function sumDue(dues: string[]): string {
  return show(dues.filter((d) => d !== 'n/a').reduce((total, d) => total + hundredths(d), 0n));
}

/**
 * A claim's figure: a settled claim's frozen due, otherwise the figure its person's last statement bound
 * it to, otherwise its amount times its person's grade's rate on the claim's date, raised to the sheet's
 * `floor` (two decimals).
 */
export function figure(claim: Claim, rates: Rate[], grade: Grade | undefined, floor: string): string {
  if (claim.settledDue !== null) return claim.settledDue;
  if (claim.stated) return claim.statedDue ?? 'n/a';
  const live = due(claim.amount, rateFor(rates, grade, claim.date));
  return live === 'n/a' || hundredths(live) >= hundredths(floor) ? live : show(hundredths(floor));
}
import { useQuery } from '@tanstack/react-query';
import { sheetQuery } from './sheetQuery';

/** The sheet's today (yyyy-mm-dd), or '' until loaded. Every default date uses this, never `new Date()`. */
export function useSheetToday(sheetId: string): string {
  return useQuery(sheetQuery(sheetId)).data?.today ?? '';
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
